// QA-only observer: captures the exact PNG blob already generated by production
// export code. It does not draw, alter, or replace the output image.
window.addEventListener('DOMContentLoaded',()=>{
 const bar=document.createElement('div');bar.style.cssText='padding:10px;background:#fff1bb;color:#243b2e;position:relative;z-index:1000;display:flex;gap:12px;align-items:center';
 const label=document.createElement('span');label.textContent='LOCAL QA · No external AI';
 const mode=document.createElement('select');mode.id='qaCaptureRun';mode.setAttribute('aria-label','QA export capture');for(const name of ['desktop-adjusted','mobile-adjusted']){const option=document.createElement('option');option.value=name;option.textContent=name;mode.append(option);}
 const load=document.createElement('button');load.id='qaLoadTerminal';load.textContent='Load terminal test';load.addEventListener('click',async()=>{const blob=await(await fetch('/qa-fixtures/terminal.png')).blob();const transfer=new DataTransfer();transfer.items.add(new File([blob],'terminal.png',{type:'image/png'}));const input=document.getElementById('fileInput');input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));});
 const error=document.createElement('select');error.setAttribute('aria-label','QA gateway error');
 for(const [value,text] of [['0','Normal mock AI'],['413','HTTP 413'],['429','HTTP 429'],['502','HTTP 502'],['503','HTTP 503'],['504','HTTP 504'],['500','HTTP 500']]){const o=document.createElement('option');o.value=value;o.textContent=text;error.append(o);}
 error.addEventListener('change',async()=>{await fetch('/qa-mode?status='+error.value,{method:'POST'});label.textContent='LOCAL QA · No external AI · '+error.selectedOptions[0].textContent;});
 bar.append(label,mode,load,error);document.body.prepend(bar);
 const preview=document.getElementById('exportPreview');new MutationObserver(async()=>{
  if(!preview.src.startsWith('blob:'))return;
  document.documentElement.dataset.qaCapture='pending';
  const blob=await(await fetch(preview.src)).blob();const result=await fetch('/qa-export?run='+encodeURIComponent(mode.value),{method:'POST',headers:{'Content-Type':'image/png'},body:blob});document.documentElement.dataset.qaCapture=result.ok?'saved':'failed';
 }).observe(preview,{attributes:true,attributeFilter:['src']});
});
